<?php
$active_menu='projects';include 'header.php';require_once __DIR__.'/../foundation.php';oecrm_require_permission($conn,'project_sprints','view');$companyId=oecrm_current_company_id($conn);$projectId=(int)($_GET['project_id']??0);$projects=mysqli_query($conn,'SELECT id,projectName FROM projectstbl WHERE company_id='.$companyId.' ORDER BY projectName');$where=$projectId?' AND s.project_id='.$projectId:'';$rows=mysqli_query($conn,'SELECT s.*,p.projectName,(SELECT COUNT(*) FROM tasktbl t WHERE t.sprint_id=s.id) task_count FROM project_sprints s JOIN projectstbl p ON p.id=s.project_id WHERE p.company_id='.$companyId.$where.' ORDER BY s.start_date DESC');
?><div id="page-wrapper" class="compact-admin-page"><div class="foundation-titlebar"><a href="projectKanban.php"><i class="fa fa-arrow-left"></i> Kanban</a><h2>Sprint Management</h2></div><div class="asset-layout"><section><div class="panel panel-default"><div class="panel-heading">Sprints</div><div class="panel-body table-responsive"><table class="table foundation-table"><thead><tr><th>Sprint</th><th>Project</th><th>Period</th><th>Tasks</th><th>Status</th></tr></thead><tbody><?php if(mysqli_num_rows($rows)===0):?><tr><td colspan="5" class="empty-cell">No sprints found.</td></tr><?php endif;?><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><strong><?php echo oecrm_h($r['name']);?></strong><small><?php echo oecrm_h($r['goal']);?></small></td><td><?php echo oecrm_h($r['projectName']);?></td><td><?php echo date('d M',strtotime($r['start_date'])).' - '.date('d M Y',strtotime($r['end_date']));?></td><td><?php echo (int)$r['task_count'];?></td><td><span class="client-status <?php echo $r['status'];?>"><?php echo ucfirst($r['status']);?></span></td></tr><?php endwhile;?></tbody></table></div></div></section><aside><?php if(oecrm_can($conn,'project_sprints','manage')):?><div class="panel panel-default"><div class="panel-heading">Create Sprint</div><div class="panel-body"><form method="post" action="sprintAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="create"><select class="form-control" name="project_id" required><option value="">Select project</option><?php while($p=mysqli_fetch_assoc($projects)):?><option value="<?php echo $p['id'];?>" <?php echo $projectId==$p['id']?'selected':'';?>><?php echo oecrm_h($p['projectName']);?></option><?php endwhile;?></select><br><input class="form-control" name="name" placeholder="Sprint name" required><br><textarea class="form-control" name="goal" placeholder="Sprint goal"></textarea><br><input class="form-control" type="date" name="start_date" required><br><input class="form-control" type="date" name="end_date" required><br><button class="btn btn-primary btn-block">Create Sprint</button></form></div></div><?php endif;?></aside></div></div><?php include 'footer.php';?>
